with lang as (select id from languages where code = 'en')
insert into toeic_tests (language_id, title, questions, exam_type)
select lang.id, 'TOEFL-like — Test 2', '{"duration_minutes": 45, "part_a": [{"question": "Complète : The dissertation ___ approved by the committee last week.", "options": ["was", "were", "is", "has"], "correct_index": 0}, {"question": "Complète : Scholars ___ debated this issue for over a century.", "options": ["has", "have", "having", "had have"], "correct_index": 1}, {"question": "Complète : The professor requires that each student ___ a topic by Monday.", "options": ["chooses", "choose", "chose", "choosing"], "correct_index": 1}, {"question": "Complète : ___ complex the theory is, it can be explained simply.", "options": ["As", "However", "Despite", "So"], "correct_index": 0}, {"question": "Complète : This is the archive ___ documents are stored digitally.", "options": ["which", "where", "who", "whose"], "correct_index": 1}, {"question": "Complète : Had the team known earlier, they ___ adjusted the plan.", "options": ["would", "would have", "will", "had"], "correct_index": 1}, {"question": "Complète : The findings ___ to be replicated in future studies.", "options": ["need", "needs", "needing", "needed"], "correct_index": 0}, {"question": "Complète : It is unlikely that the theory ___ disproven soon.", "options": ["is", "be", "will be", "was"], "correct_index": 2}, {"question": "Complète : The seminar covers topics ___ range from ethics to policy.", "options": ["who", "which", "whose", "where"], "correct_index": 1}, {"question": "Complète : ___ the data being incomplete, the team drew preliminary conclusions.", "options": ["Although", "Despite", "Because", "So"], "correct_index": 1}, {"question": "Complète : The lecture hall ___ renovated over the summer.", "options": ["was", "were", "has", "have"], "correct_index": 0}, {"question": "Complète : She is one of the few researchers who ___ this method.", "options": ["use", "uses", "using", "used to"], "correct_index": 0}, {"question": "Complète : The proposal ___ before the funding is approved.", "options": ["must review", "must be reviewed", "must reviewed", "must reviewing"], "correct_index": 1}, {"question": "Complète : What matters most ___ the quality of the evidence.", "options": ["is", "are", "was being", "were"], "correct_index": 0}, {"question": "Complète : The article was written ___ a leading expert in the field.", "options": ["by", "from", "with", "at"], "correct_index": 0}, {"question": "Complète : Not until the results were analyzed ___ the pattern become clear.", "options": ["did", "does", "had", "was"], "correct_index": 0}, {"question": "Complète : The professor''s argument, ___ compelling, lacked sufficient evidence.", "options": ["although", "while", "despite", "so"], "correct_index": 1}, {"question": "Complète : Students are advised ___ their sources carefully.", "options": ["cite", "to cite", "citing", "cited"], "correct_index": 1}, {"question": "Complète : The theory has since ___ modified to account for new evidence.", "options": ["be", "been", "being", "was"], "correct_index": 1}, {"question": "Complète : This is the professor ___ research changed the field.", "options": ["who", "whom", "whose", "which"], "correct_index": 2}, {"question": "Complète : The results, once ___, will be published.", "options": ["confirm", "confirmed", "confirming", "to confirm"], "correct_index": 1}, {"question": "Complète : Rarely ___ such consensus among researchers.", "options": ["there is", "is there", "there was", "was there"], "correct_index": 1}, {"question": "Complète : The methodology section ___ how the data was gathered.", "options": ["describe", "describes", "describing", "described"], "correct_index": 1}, {"question": "Complète : It was the sample size ___ limited the study''s validity.", "options": ["that", "who", "which is", "what"], "correct_index": 0}, {"question": "Complète : The committee will meet ___ discuss the proposal.", "options": ["for", "to", "so", "that"], "correct_index": 1}, {"question": "Complète : Given ___ constraints, the results are still notable.", "options": ["the", "of the", "a", "an"], "correct_index": 0}, {"question": "Complète : The professor insisted ___ we revise our thesis statements.", "options": ["that", "for", "on", "to"], "correct_index": 0}, {"question": "Complète : The report ___ submitted electronically from now on.", "options": ["must", "must be", "must to be", "musting"], "correct_index": 1}, {"question": "Complète : Few theories ___ withstood as much scrutiny.", "options": ["has", "have", "having", "had"], "correct_index": 1}, {"question": "Complète : The study''s conclusions ___ further investigation.", "options": ["warrant", "warrants", "warranting", "warranted to"], "correct_index": 0}], "part_b": [{"title": "Extrait académique (astronomie)", "passage": "Black holes form when massive stars collapse under their own gravity at the end of their life cycle. The resulting gravitational pull is so strong that not even light can escape, which is why they appear completely dark and can only be detected through their effects on nearby matter.", "questions": [{"question": "How do black holes form?", "options": ["From colliding planets", "Massive stars collapsing under gravity", "Exploding asteroids", "Cooling gas clouds"], "correct_index": 1}, {"question": "Why can''t light escape a black hole?", "options": ["It''s too far away", "The gravitational pull is extremely strong", "Light doesn''t exist there", "It''s a myth"], "correct_index": 1}, {"question": "How do scientists detect black holes?", "options": ["Direct visual observation", "Their effects on nearby matter", "Radio signals they emit", "They cannot be detected"], "correct_index": 1}, {"question": "When do black holes typically form?", "options": ["At the birth of a star", "At the end of a star''s life cycle", "Randomly at any time", "Only during supernovae explosions"], "correct_index": 1}, {"question": "What type of stars form black holes?", "options": ["Small stars", "Massive stars", "Dying planets", "Comets"], "correct_index": 1}, {"question": "Why do black holes appear dark?", "options": ["They absorb all color", "No light can escape them", "They are very cold", "They don''t actually exist"], "correct_index": 1}]}, {"title": "Extrait académique (sociologie)", "passage": "Social capital refers to the networks of relationships that enable a society to function effectively. Researchers argue that communities with higher levels of social capital tend to experience lower crime rates, better public health outcomes, and more effective governance.", "questions": [{"question": "What is social capital?", "options": ["A type of currency", "Networks of relationships enabling society to function", "A government policy", "A form of taxation"], "correct_index": 1}, {"question": "What do communities with high social capital tend to have?", "options": ["Higher crime rates", "Lower crime rates", "No public services", "Weaker governance"], "correct_index": 1}, {"question": "What else is associated with high social capital?", "options": ["Worse public health", "Better public health outcomes", "Higher taxes", "Less education"], "correct_index": 1}, {"question": "What do researchers argue about governance?", "options": ["It becomes less effective", "It becomes more effective", "It disappears", "It has no connection"], "correct_index": 1}, {"question": "What is the main subject of the passage?", "options": ["Economic policy", "Social capital and community outcomes", "A historical event", "A scientific experiment"], "correct_index": 1}, {"question": "What kind of relationships does social capital refer to?", "options": ["Only family relationships", "Networks within a society", "International relations", "Business contracts only"], "correct_index": 1}]}, {"title": "Extrait académique (chimie)", "passage": "Catalysts are substances that speed up chemical reactions without being consumed in the process. They work by lowering the activation energy required for a reaction to occur, allowing reactions to proceed faster and often at lower temperatures than would otherwise be needed.", "questions": [{"question": "What do catalysts do?", "options": ["Slow down reactions", "Speed up chemical reactions", "Stop reactions completely", "Change the products entirely"], "correct_index": 1}, {"question": "Are catalysts consumed in the reaction?", "options": ["Yes, completely", "No, they are not consumed", "Only partially", "Not mentioned"], "correct_index": 1}, {"question": "How do catalysts work?", "options": ["By raising activation energy", "By lowering activation energy", "By adding more heat", "By removing reactants"], "correct_index": 1}, {"question": "What effect can catalysts have on temperature requirements?", "options": ["They require higher temperatures", "They allow lower temperatures", "They have no effect", "They eliminate temperature needs"], "correct_index": 1}, {"question": "What is activation energy related to?", "options": ["The energy needed to start a reaction", "The final product''s mass", "The color of the reaction", "The catalyst''s weight"], "correct_index": 0}, {"question": "What is the overall topic of this passage?", "options": ["A biology process", "How catalysts affect chemical reactions", "A historical discovery", "A mathematical formula"], "correct_index": 1}]}, {"title": "Extrait académique (anthropologie)", "passage": "Cultural relativism is the principle that a person''s beliefs and practices should be understood based on that person''s own culture, rather than judged against the standards of another. This approach encourages anthropologists to avoid ethnocentric bias when studying different societies.", "questions": [{"question": "What is cultural relativism?", "options": ["Judging cultures by one universal standard", "Understanding beliefs based on one''s own culture", "Ignoring cultural differences", "A type of government"], "correct_index": 1}, {"question": "What does this approach help avoid?", "options": ["Scientific accuracy", "Ethnocentric bias", "Cultural exchange", "Historical research"], "correct_index": 1}, {"question": "Who is encouraged to use this approach?", "options": ["Politicians", "Anthropologists", "Economists", "Engineers"], "correct_index": 1}, {"question": "What should NOT be done, according to the passage?", "options": ["Studying other cultures", "Judging by another culture''s standards", "Learning languages", "Conducting field research"], "correct_index": 1}, {"question": "What field is most associated with this concept?", "options": ["Physics", "Anthropology", "Chemistry", "Astronomy"], "correct_index": 1}, {"question": "What is the main purpose of cultural relativism?", "options": ["To rank cultures", "To promote fair understanding of cultures", "To eliminate cultural study", "To standardize all cultures"], "correct_index": 1}]}, {"title": "Extrait académique (neurosciences)", "passage": "Neuroplasticity refers to the brain''s ability to reorganize itself by forming new neural connections throughout life. This capacity allows the brain to adapt to new experiences, recover from injury, and compensate for lost functions, challenging the older view that brain structure is fixed after childhood.", "questions": [{"question": "What is neuroplasticity?", "options": ["The brain''s fixed structure", "The brain''s ability to reorganize and form new connections", "A type of brain injury", "A memory disorder"], "correct_index": 1}, {"question": "When does this capacity exist?", "options": ["Only in childhood", "Throughout life", "Only after injury", "Only in old age"], "correct_index": 1}, {"question": "What can the brain do because of neuroplasticity?", "options": ["Stay unchanged forever", "Adapt to new experiences and recover from injury", "Stop functioning after childhood", "Only lose functions"], "correct_index": 1}, {"question": "What older view does this challenge?", "options": ["That the brain changes constantly", "That brain structure is fixed after childhood", "That the brain has no functions", "That injuries always heal"], "correct_index": 1}, {"question": "What does neuroplasticity allow the brain to compensate for?", "options": ["Excess energy", "Lost functions", "Extra neurons", "Sleep deprivation"], "correct_index": 1}, {"question": "What is the main topic of the passage?", "options": ["A historical event", "The brain''s capacity for change", "A surgical technique", "A psychological disorder"], "correct_index": 1}]}]}'::jsonb, 'toefl'
from lang;

